fn function_where_clause(
    &mut self, generics: &mut [GenericParam], outlives: &mut Vec<LifetimePredicate>,
) -> Result<Vec<WherePredicate>, Diagnostic> {
    let mut predicates = Vec::new();
    if !self.take("where") {
        return Ok(predicates);
    }
    while !self.is("{") && !self.is(";") && !self.is("=") {
        let span = self.token().span;
        if self.token().kind == TokenKind::Lifetime {
            let target = NamedLifetime { name: self.token().text.clone(), span };
            self.at += 1;
            self.expect(":")?;
            let mut bounds = Vec::new();
            loop {
                if self.token().kind != TokenKind::Lifetime {
                    return Err(self.unsupported("lifetime-outlives predicate with a non-lifetime bound"));
                }
                bounds.push(NamedLifetime { name: self.token().text.clone(), span: self.token().span });
                self.at += 1;
                if !self.take("+") { break; }
            }
            outlives.push(LifetimePredicate { target, bounds, span: self.finish_span(span) });
            if !self.take(",") { break; }
            continue;
        }
        let target = self.ty()?;
        self.expect(":")?;
        let bounds = self.bounds()?;
        for bound in &bounds {
            if matches!(&self.program.types[*bound].kind, Type::Path(path) if path.name.starts_with('\'')) {
                return Err(Diagnostic::new(self.program.types[*bound].span, "E_UNSUPPORTED",
                    "type-outlives where predicates are not implemented"));
            }
        }
        let name = match &self.program.types[target].kind {
            Type::Path(path) if path.qualification.is_none() && path.args.is_empty() && path.bindings.is_empty() => Some(path.name.clone()),
            _ => None,
        };
        let mut found = false;
        let mut i = 0;
        while i < generics.len() {
            if name.as_ref().is_some_and(|name| generics[i].name == *name) {
                for bound in &bounds {
                    generics[i].bounds.push(*bound);
                }
                found = true;
                break;

